#include <vector>
#include <iostream>

int main() {
    std::vector<int> v;
    v.reserve(4);
    std::cout << "size=" << v.size() << "\n";   // 0: reserve touched capacity only
    for (int i = 0; i < 6; ++i) v.push_back(i);   // reallocates once, past 4
    std::cout << "size=" << v.size() << "\n";
    for (int x : v) std::cout << x << " ";
    std::cout << "\n";
}

#include <vector>
#include <iostream>

int main() {
    std::vector<int> v{1, 2, 3};
    int* p = &v[0];        // points into the current buffer
    v.reserve(100);        // reallocation: p now dangles
    // std::cout << *p;    // undefined behaviour - old buffer freed
    v.push_back(4);        // fine: size 4 <= capacity 100, no realloc
    std::cout << v[0] << " " << v.size() << "\n";
}

#include <array>
#include <iostream>

int main() {
    constexpr std::array<double, 3> tenorRates{0.031, 0.034, 0.039};
    std::cout << "n=" << tenorRates.size()
              << " first=" << tenorRates[0] << "\n";
}

